#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""PDF 文档解析器模块（使用 PyMuPDF/fitz）。"""

from typing import List, Optional, Dict, Any
import logging

try:
    import fitz
    FITZ_AVAILABLE = True
except ImportError:
    FITZ_AVAILABLE = False

from .base_parser import BaseDocumentParser, ParsedDocument


class PDFParser(BaseDocumentParser):
    """PDF 文档解析器。"""

    SUPPORTED_EXTENSIONS: List[str] = ['.pdf']

    def __init__(self, password: Optional[str] = None, logger: Optional[logging.Logger] = None) -> None:
        super().__init__(logger)
        if not FITZ_AVAILABLE:
            raise ImportError("PyMuPDF (fitz) 未安装。请运行: pip install pymupdf")
        self.password = password

    def parse(self, file_path: str) -> ParsedDocument:
        self.logger.info(f"开始解析 PDF 文件: {file_path}")
        try:
            self.validate_file(file_path)
            doc = fitz.open(file_path)

            if doc.is_encrypted:
                if self.password and not doc.authenticate(self.password):
                    return self._create_error_result(file_path, "PDF 密码错误")
                elif not self.password:
                    return self._create_error_result(file_path, "PDF 已加密，需要密码")

            metadata = self._extract_metadata(doc)
            page_texts = [doc.load_page(i).get_text("text") for i in range(doc.page_count)]
            full_text = self._clean_text("\n\n".join([t.strip() for t in page_texts if t.strip()]))
            doc.close()

            self.logger.info(f"PDF 解析完成: {len(page_texts)} 页, {len(full_text)} 字符")
            return ParsedDocument(
                file_path=file_path, file_name="", file_type=".pdf",
                text_content=full_text, page_texts=page_texts, metadata=metadata, success=True,
            )
        except Exception as e:
            self.logger.error(f"PDF 解析失败: {str(e)}")
            return self._create_error_result(file_path, str(e))

    def extract_text(self, file_path: str) -> str:
        result = self.parse(file_path)
        if not result.success:
            raise Exception(result.error_message)
        return result.text_content

    def _extract_metadata(self, doc) -> Dict[str, Any]:
        m = doc.metadata or {}
        return {
            "title": m.get("title", ""), "author": m.get("author", ""),
            "page_count": doc.page_count, "is_encrypted": doc.is_encrypted,
        }
